-- Private preview only: snapshots of the repository's MNC and Mozzi brand/menu seeds.
-- Existing preview edits are preserved on repeat deployment.

insert into public.preview_businesses (slug, display_name, tagline, font_preset, colors, categories, reward_title, reward_threshold, status)
select b->>'slug', b->>'display_name', b->>'tagline', b->>'font_preset', b->'colors', b->'categories', b->>'reward_title', (b->>'reward_threshold')::integer, b->>'status'
from (select '{"slug":"mnc","display_name":"MNC CONCEPT","tagline":"","font_preset":"modern","colors":{"background":"#FFFFFF","surface":"#FFFFFF","text":"#0A0A0A","muted":"#717182","accent":"#000000","accentText":"#FFFFFF"},"categories":[{"key":"MATCHA","label":"MATCHA"},{"key":"NAPOJE","label":"NAPOJE"},{"key":"JEDZENIE","label":"JEDZENIE"}],"reward_title":"Your reward is ready!","reward_threshold":10,"status":"ready"}'::jsonb as b) x
on conflict (slug) do nothing;

insert into public.preview_balances (business_slug, points) values ('mnc', 0) on conflict do nothing;

insert into public.preview_menu_items (business_slug, category_key, section, title, description, price_cents, position)
