insert into public.preview_businesses (slug, display_name, tagline, font_preset, colors, categories, reward_title, reward_threshold, status)
select b->>'slug', b->>'display_name', b->>'tagline', b->>'font_preset', b->'colors', b->'categories', b->>'reward_title', (b->>'reward_threshold')::integer, b->>'status'
from (select '{"slug":"mozzi","display_name":"Mozzi","tagline":"","font_preset":"modern","colors":{"background":"#FFFFFF","surface":"#FFFDF8","text":"#1F2A24","muted":"#6F766F","accent":"#1F4F3A","accentText":"#FFFFFF"},"categories":[{"key":"KAWA","label":"KAWA"},{"key":"ŚNIADANIA","label":"ŚNIADANIA"},{"key":"DESERY","label":"DESERY"},{"key":"WINO","label":"WINO"}],"reward_title":"Your Mozzi coffee reward is ready.","reward_threshold":10,"status":"ready"}'::jsonb as b) x
on conflict (slug) do nothing;

insert into public.preview_balances (business_slug, points) values ('mozzi', 0) on conflict do nothing;

